def process_hran_variable_list(variable_list):
    alias_list = []
    for entry in variable_list:
        if 'MASTER' in entry or 'SLAVE' in entry:
            alias_list.append(entry.title())
    return alias_list


def add_dicts(*args):
    final = {}
    for entry in args:
        final.update(entry)

    return final
